(function(global){
'use strict';
// English-word membership uses a Bloom filter generated from CMUdict plus a small TOK-domain allowlist.
// Bloom filters can produce rare false positives; this is an anti-filler completion check, not a language assessment.
const M=2097152, K=7, MASK=M-1;
const DATA='';
const DOMAIN=new Set(["aesthetic", "aesthetics", "analogue", "arousal", "artistic", "borderline", "cinematography", "classification", "classificatory", "classified", "classify", "commodification", "conditional", "counterargument", "curatorial", "epistemic", "erotica", "explicitness", "formulaic", "fuses", "hypothetical", "institutional", "interpretive", "khajuraho", "levinson", "maes", "mapplethorpe", "metacognition", "miller", "misogyny", "objectification", "pompeii", "pornographic", "pornography", "provocation", "reframe", "reframed", "reframing", "schneemann", "sexuality", "spectatorship", "tok"]);
let bytes=null;
function getBytes(){
  if(bytes)return bytes;
  const raw=atob(DATA); bytes=new Uint8Array(raw.length);
  for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
  return bytes;
}
function fnv32(s){
  let h=0x811c9dc5;
  for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0;}
  return h>>>0;
}
function isWord(raw){
  const w=String(raw||'').toLowerCase().replace(/[’]/g,"'");
  if(DOMAIN.has(w))return true;
  if(!/^[a-z]+(?:'[a-z]+)?$/.test(w))return false;
  const arr=getBytes(), h1=fnv32(w), h2=(fnv32(w+'#')|1)>>>0;
  for(let i=0;i<K;i++){const idx=(h1+Math.imul(i,h2))&MASK;if((arr[idx>>>3]&(1<<(idx&7)))===0)return false;}
  return true;
}
global.TOKDictionary={isWord,sizeHint:124096,falsePositiveNote:'Bloom-filter membership; rare false positives are possible.'};
})(window);
